/* GDI+ flat API lives in gdiplus.dll but its header is C++-only, so the
 * symbols below are resolved by name at first use. */
static void* vb6_di_gdiplus_proc(const char* name) {
    static HMODULE mod = NULL;
    if (mod == NULL) { mod = LoadLibraryA("gdiplus.dll"); }
    return (mod != NULL) ? (void*)GetProcAddress(mod, name) : NULL;
}

